const test = require("node:test");
const assert = require("node:assert");

const { startServer, api } = require("./helpers");

test("bulk-transfer-owner: is atomic - a missing slug leaves everything untouched", async () => {
  const { base, close } = startServer();
  try {
    await api(base, "POST", "/api/links", { url: "https://a.example.com", slug: "link-a", owner: "dev" });

    const resp = await api(base, "POST", "/api/links/bulk-transfer-owner", {
      toOwner: "newowner",
      slugs: ["link-a", "does-not-exist"],
    });
    assert.strictEqual(resp.status, 404);

    const check = await api(base, "GET", "/api/links/link-a");
    assert.strictEqual(check.json.owner, "dev");
  } finally {
    await close();
  }
});

test("bulk-transfer-owner: respects destination capacity", async () => {
  const { base, close } = startServer();
  try {
    for (let i = 0; i < 3; i++) {
      await api(base, "POST", "/api/links", { url: `https://example.com/${i}`, owner: "newowner" });
    }
    await api(base, "POST", "/api/links", { url: "https://example.com/free", slug: "free-link", owner: "dev" });

    const resp = await api(base, "POST", "/api/links/bulk-transfer-owner", {
      toOwner: "newowner",
      slugs: ["free-link"],
    });
    assert.strictEqual(resp.status, 400);
  } finally {
    await close();
  }
});

